/**
 * Match a query against every field in the registry (registry order).
 * Never throws: a malformed regex is skipped, not fatal.
 */
export function matchDomains(query) {
  if (!query) return [];
  const q = ' ' + String(query).toLowerCase() + ' ';
  const out = [];
  for (const d of DOMAINS) {
    try {
      if (d.re && d.re.test(q)) out.push(d);
    } catch { /* skip bad regex */ }
  }
  return out;
}

/** Primary field match (first in registry order), or null. */
export function matchDomain(query) {
  return matchDomains(query)[0] || null;
}
